/**
 * lib/rastreabilidade/macSlot5.ts — matriz de rastreabilidade do MAC do slot 5.
 *
 * ALIMENTADO em 2026-07-29: os 768 itens do checklist compatibilizado com o Despacho Geral
 * Oficial (ver migration 2026_07_29_mac_compatibilizacao_despacho_oficial.sql) entram aqui como
 * consumidores da mesma infraestrutura do LIP — tipos, testes, tela e filtros não mudaram.
 *
 * ── O QUE CADA ITEM DECLARA ──────────────────────────────────────────────────
 * Todo item do MAC é MANUAL: só o analista decide (conforme/não conforme/não se aplica), na tela
 * de análise (`analises_mac.itens`, mapa item_id→status). Nenhum item consome IA ou é lido
 * automaticamente hoje — é a mesma declaração já usada em `atendeAcessibilidade` no LIP.
 *
 * `codigo` é o `id` (UUID) de `mac_checklist_itens` — já é estável e não muda quando o item é
 * reordenado ou quando o grupo ganha itens novos (ordem 9000+ da compatibilização).
 *
 * O texto do item, o fundamento completo e o vínculo com o BIP (`mac_bip_vinculos`) ficam SÓ no
 * banco — não duplicados aqui. A matriz registra o que precisa para a trava de rastreabilidade
 * (declaração, método, quem preenche), não o conteúdo do checklist.
 *
 * ── GRUPOS ────────────────────────────────────────────────────────────────────
 * Os 48 grupos, na ordem real do checklist (menor `ordem` de cada grupo em produção). O grupo
 * ACESSIBILIDADE - NBR9050 mantém o escopo congelado já documentado antes desta etapa.
 */

